{"path": "robot_name.py", "content": "import random
import string


class Robot:
    """A robot with a unique random name of the form AA000."""

    _used_names = set()

    def __init__(self):
        self.name = self._generate_unique_name()

    @classmethod
    def _generate_unique_name(cls):
        if len(cls._used_names) >= 26 * 26 * 1000:
            raise RuntimeError("All robot names are in use")
        while True:
            name = "".join(random.choice(string.ascii_uppercase) for _ in range(2))
            name += "".join(random.choice(string.digits) for _ in range(3))
            if name not in cls._used_names:
                cls._used_names.add(name)
                return name

    def reset(self):
        """Wipe the robot's name and give it a fresh unique one."""
        old_name = self.name
        # Generate the new name before releasing the old one, so the robot
        # never gets its previous name back.
        self.name = self._generate_unique_name()
        Robot._used_names.discard(old_name)
